//! A page, as defined by `page!` in its module.

use crate::content::Document;
use crate::lang::Lang;
use maud::Markup;

/// Generated by `setzer::page!` as `pub static PAGE`. Fields are filled in
/// by the macro; pages refer to each other through these statics.
pub struct PageDef {
    /// `module_path!()` of the page; the route is the part below `www`.
    pub module: &'static str,
    /// A fixed path such as `/404.html`, in every language (`/de/404.html`).
    pub path: Option<&'static str>,
    pub render: RenderFn,
    pub meta: fn(Lang) -> Meta,
    pub feed: Option<fn(Lang) -> Feed>,
}

pub enum RenderFn {
    /// One page.
    Single(fn(Lang) -> Markup),
    /// One page per document, at `<parent route><slug>/`.
    Each(&'static [Document], fn(&'static Document, Lang) -> Markup),
}

/// Implemented by every struct `content!` generates: the `title` and
/// `description` keys, if the content file has them. `page!` uses it for
/// the frame's `<head>` and as link text for `[[page]]` links.
pub trait ContentMeta {
    fn title(&self) -> Option<&'static str>;
    fn description(&self) -> Option<&'static str>;
}

/// What the frame needs to know about a page for `<head>`.
#[derive(Clone, Copy, Default)]
pub struct Meta {
    pub title: Option<&'static str>,
    pub description: Option<&'static str>,
}

pub struct Feed {
    pub title: String,
    pub description: String,
    pub items: Vec<FeedItem>,
}

pub struct FeedItem {
    pub title: String,
    /// Root-relative, already language prefixed (from `Doc::href`).
    pub href: String,
    pub description: Option<String>,
    pub date: Option<chrono::DateTime<chrono::FixedOffset>>,
}

impl PageDef {
    /// Language-independent route: the module path below `www`, `_` as `-`.
    /// `crate::www` itself is `/`. For `Each` pages, each document's slug
    /// takes the place of the module's own name.
    pub fn route(&self) -> String {
        if let Some(p) = self.path {
            return p.to_string();
        }
        let segments: Vec<&str> = self.module.split("::").collect();
        let Some(start) = segments.iter().position(|s| *s == "www") else {
            panic!(
                "page module {} is not below a module named `www`",
                self.module
            )
        };
        let mut route = String::from("/");
        let below = &segments[start + 1..];
        let below = match self.render {
            // a collection's own folder name is replaced by each slug
            RenderFn::Each(..) => &below[..below.len().saturating_sub(1)],
            RenderFn::Single(_) => below,
        };
        for seg in below {
            route.push_str(&seg.replace('_', "-"));
            route.push('/');
        }
        route
    }

    /// The page's title in `lang`, falling back to its route.
    pub fn title(&self, lang: Lang) -> &'static str {
        (self.meta)(lang).title.unwrap_or(self.module)
    }
}

/// A post as a feed item: `post::documents(lang).map(FeedItem::from)`.
impl From<&crate::content::Doc> for FeedItem {
    fn from(doc: &crate::content::Doc) -> FeedItem {
        FeedItem {
            title: doc.title.into(),
            href: doc.href(),
            description: doc.description.map(Into::into),
            date: doc.datetime(),
        }
    }
}
